function getCategoryIcon(iconName, size = 18) {
  switch (iconName) {
    case 'ShoppingBag': return <ShoppingBag size={size} />;
    case 'Package': return <Package size={size} />;
    case 'Coins': return <Coins size={size} />;
    case 'Sparkles': return <Sparkles size={size} />;
    case 'Pill': return <Pill size={size} />;
    case 'HeartPulse': return <HeartPulse size={size} />;
    case 'Zap': return <Zap size={size} />;
    case 'Droplets': return <Droplets size={size} />;
    default: return <Gift size={size} />;
  }
}

let _on429Handler = null;
async function authFetch(url, options = {}) {
  const { data } = await supabase.auth.getSession();
  const token = data.session?.access_token;
  const headers = {
    ...(options.headers || {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
  const res = await fetch(url, { ...options, headers });
  if (res.status === 429) _on429Handler?.();
  return res;
}

// Helper for smart pagination (always shows first & last pages, plus window around active page)
function getPaginationItems(current, total) {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  if (current <= 4) {
    return [1, 2, 3, 4, 5, '...', total];
  }
  if (current >= total - 3) {
    return [1, '...', total - 4, total - 3, total - 2, total - 1, total];
  }
  return [1, '...', current - 1, current, current + 1, '...', total];
}

